'use strict';
// 2の段：保護者提供のEllis音声。無音部分で区切り、元のMP3をそのまま使います。
const BundledChants=(()=>{
 const encoded='';
 const ranges=[[0.2,1.47],[2.48,3.71],[4.6,5.97],[6.93,8.17],[9.11,10.16],[10.93,12.23],[12.88,14.14],[14.91,16.31],[17,18.602]];
 let blob;
 function clip(key){const match=/^chant:2-([1-9])$/.exec(key);if(!match)return null;blob ||= new Blob([Uint8Array.from(atob(encoded),c=>c.charCodeAt(0))],{type:'audio/mpeg'});const [start,end]=ranges[Number(match[1])-1];return {blob,start,duration:end-start};}
 return {clip};
})();
